// 将 x 四舍五入到两位小数。
export function round(x) {
  return Math.round(x * 100) / 100;
}

// 将数字四舍五入到 2 位小数（常见金额精度）。
export function round(x) {
  return Math.round(x * 100) / 100;
}

/**
 * 将数字四舍五入到 2 位小数。
 *
 * @param {number} x 要处理的数字。
 * @returns {number} 保留 2 位小数后的结果。
 */
export function round(x) {
  const factor = 100;
  return Math.round(x * factor) / factor;
}

/**
 * 将数字四舍五入到指定的小数位数。
 *
 * @param {number} x 待处理的数字。
 * @param {number} [digits=2] 保留的小数位数，默认为 2。
 * @returns {number} 四舍五入后的数字。
 */
export function round(x, digits = 2) {
  const factor = 10 ** digits;
  return Math.round(x * factor) / factor;
}

// 将数字四舍五入到指定的小数位数。
// 默认保留 2 位小数；可通过第二个参数 digits 自定义保留位数。
export function round(x, digits = 2) {
  const factor = 10 ** digits;
  return Math.round(x * factor) / factor;
}

/**
 * 把 x 保留 2 位小数，四舍五入。
 *
 * 实现说明：
 * - 使用 Math.round 结合缩放/还原来避免 IEEE 754 浮点直接乘带来的精度问题：
 *   先把 x 放大 100 倍，四舍五入后再除以 100。
 * - 通过 toFixed(2) + Number() 把结果规整成数字，避免返回字符串。
 *
 * @param {number} x 待处理的数字
 * @returns {number} 保留 2 位小数、四舍五入后的数字
 */
export function round(x) {
  const scaled = Math.round(x * 100);
  return Number((scaled / 100).toFixed(2));
}

/**
 * 将数字四舍五入保留 2 位小数。
 * @param {number} x 待处理的数字
 * @returns {number} 保留 2 位小数的结果
 */
export function round(x) {
  return Math.round(x * 100) / 100;
}

